const mk = (p) => tools.call("document-intelligence_save_product", p);
const results = await Promise.all([
  mk({ sku: "PNL-550", name: "Solar panel 550W", unit: "unit", unit_price: 650, tax_code: "ST10" }),
  mk({ sku: "INV-10K", name: "Hybrid inverter 10kW", unit: "unit", unit_price: 5200, tax_code: "ST10" }),
  mk({ sku: "SVC-INSTALL", name: "Installation service", unit: "job", unit_price: 3000, tax_code: "SV8" })
]);
emit(results.map(r => r.ok ? { ok: true, sku: r.data.product?.sku, name: r.data.product?.name, price: r.data.product?.unit_price, tax: r.data.product?.tax_code, changed: r.data.changed } : r.error));

const parse = (r) => {
  if (!r.ok) return { error: r.error };
  const c = r.data?.content;
  if (Array.isArray(c)) { try { return JSON.parse(c[0].text); } catch { return r.data; } }
  return r.data;
};
const pkg = await tools.call("document-intelligence_save_package", {
  code: "PKG-10KWP",
  name: "10kWp rooftop package",
  price: 22000,
  tax_code: "SV8",
  items: [
    { product: "PNL-550", quantity: 18 },
    { product: "INV-10K", quantity: 1 }
  ]
});
emit({ saved: parse(pkg) });
const read = await tools.call("document-intelligence_get_package", { ref: "PKG-10KWP" });
emit({ readback: parse(read) });
